import{_ as t,o,c as n,a0 as i}from"./chunks/framework.iBgbCoJu.js";const g=JSON.parse('{"title":"Frontend (client-ui)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/frontend/index.md","filePath":"reference/frontend/index.md"}'),a={name:"reference/frontend/index.md"};function s(r,e,c,d,l,h){return o(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="frontend-client-ui" tabindex="-1">Frontend (client-ui) <a class="header-anchor" href="#frontend-client-ui" aria-label="Permalink to &quot;Frontend (client-ui)&quot;">​</a></h1><p>The frontend is a Nuxt 4 SSR web application that provides the user interface for managing projects, analyses, nodes, and platform administration.</p><h2 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Development (from repo root)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client-ui</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> privateaim/hub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui</span></span></code></pre></div><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><strong>Core API</strong> — REST API for all domain operations</li><li><strong>Authup</strong> — OAuth2 identity provider (login, registration, permissions)</li></ul><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>NUXT_PUBLIC_CORE_URL</code></td><td>—</td><td>Core API base URL</td></tr><tr><td><code>NUXT_PUBLIC_AUTHUP_URL</code></td><td>—</td><td>Authup URL</td></tr><tr><td><code>NUXT_PUBLIC_AUTHUP_CLIENT_ID</code></td><td><code>admin-console</code></td><td>OAuth2 client used for the login (authorization-code) flow</td></tr><tr><td><code>NUXT_PUBLIC_ACCOUNT_URL</code></td><td><code>&lt;NUXT_PUBLIC_AUTHUP_URL&gt;/account</code></td><td>Authup account console, linked from the &quot;Account&quot; sidebar entry</td></tr><tr><td><code>NUXT_PUBLIC_STORAGE_URL</code></td><td>—</td><td>Storage service URL</td></tr><tr><td><code>NUXT_PUBLIC_TELEMETRY_URL</code></td><td>—</td><td>Telemetry service URL</td></tr><tr><td><code>NUXT_PUBLIC_MESSENGER_URL</code></td><td>—</td><td>Messenger service URL</td></tr></tbody></table><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>The UI signs in with the <strong>OAuth2 Authorization Code flow (PKCE)</strong> — credentials are never entered in the Hub UI itself. On the login page the user picks a <strong>realm</strong> (<code>ARealmGrid</code>, which reveals a search field once more than 8 realms exist); the app then builds an authorize URL and redirects to Authup&#39;s <code>/authorize</code> endpoint, where the login form and configured identity providers live. Authup redirects back to <code>&lt;ui-origin&gt;/login/callback</code>, and the <code>@authup/client-web-nuxt</code> routing interceptor exchanges the authorization code for a session.</p><p>When the user was sent to the login page from a deep link, the post-login destination rides in the callback URI&#39;s <strong>own query</strong> (<code>&lt;ui-origin&gt;/login/callback?redirect=%2Fprojects</code>), so the authorization server carries it back and the interceptor navigates there after the exchange. The same string is replayed byte-for-byte at the <code>/token</code> exchange (RFC 6749 §4.1.3).</p><p>The OAuth client is configurable via <code>NUXT_PUBLIC_AUTHUP_CLIENT_ID</code> (default: <code>admin-console</code>, an Authup built-in client provisioned for every realm). The configured client <strong>must</strong> register <code>&lt;ui-origin&gt;/login/callback**</code> as an allowed redirect URI — note the trailing <code>**</code>. A <code>&lt;ui-origin&gt;/**</code> pattern (what <code>TRUSTED_ORIGINS</code> generates) covers it as well.</p><div class="warning custom-block"><p class="custom-block-title">Upgrading to Authup &gt;= 1.0.0-beta.63</p><p>An <strong>exact</strong> <code>&lt;ui-origin&gt;/login/callback</code> registration is no longer sufficient. The post-login destination now travels in the callback URI&#39;s query, and Authup matches a redirect URI against the full canonical URL <strong>including</strong> its query string (<code>isSimpleURLMatch</code>). A deep-link login against an exactly-registered client is refused at the authorize step, while a login from the bare login page still succeeds — so the breakage looks intermittent.</p><p>Widen the client&#39;s <code>redirectUri</code> (a comma-separated glob list, where <code>*</code> stays inside a path segment and <code>**</code> matches the rest) to <code>&lt;ui-origin&gt;/login/callback**</code> before upgrading.</p></div><div class="warning custom-block"><p class="custom-block-title">Upgrading from Authup &lt; 1.0.0-beta.59</p><p>Authup beta.59 removed the shared <code>web</code> system client that used to be provisioned for every realm (<a href="https://github.com/authup/authup/pull/3379" target="_blank" rel="noreferrer">authup#3379</a>). Existing <code>web</code> rows survive and keep working, but they no longer track <code>PUBLIC_URL</code> / <code>TRUSTED_ORIGINS</code> changes, and realms created after the upgrade get no <code>web</code> client at all — which is why the default moved to <code>admin-console</code>.</p><p>A deployment serving the UI from its own origin should register a <strong>dedicated</strong> client (once per realm, e.g. via a wildcard <code>realms[]</code> provisioning entry named <code>&quot;*&quot;</code>) and point <code>NUXT_PUBLIC_AUTHUP_CLIENT_ID</code> at it, rather than sharing Authup&#39;s console client.</p></div><h2 id="account-self-service" tabindex="-1">Account Self-Service <a class="header-anchor" href="#account-self-service" aria-label="Permalink to &quot;Account Self-Service&quot;">​</a></h2><p>The UI has <strong>no settings area of its own</strong>. Profile, password, authenticators, sessions and connected applications live in <strong>Authup&#39;s account console</strong>, served by Authup&#39;s server-core on the IdP origin as of <code>v1.0.0-beta.59</code>. Keeping a second, thinner surface in the UI would only split the account UX across two origins.</p><p>The header&#39;s account icon links straight at <code>&lt;NUXT_PUBLIC_ACCOUNT_URL&gt;/?ref=&lt;ui-origin&gt;&amp;realmId=&lt;session-realm&gt;</code>, defaulting to <code>&lt;NUXT_PUBLIC_AUTHUP_URL&gt;/account</code>. It is the only entry point — the sidebar carries no account entry, so the one link that leaves for the IdP origin sits in one place rather than two. The console renders the <code>ref</code> origin as a back link after validating it against the trusted app origins; the UI origin is already required to be trusted for the login callback, so this needs no extra deployment configuration. Set <code>NUXT_PUBLIC_ACCOUNT_URL</code> for deployments where the console is not reachable under <code>&lt;NUXT_PUBLIC_AUTHUP_URL&gt;/account</code>.</p><p><code>realmId</code> is a safety net for the session mismatch between the two origins: the UI&#39;s session outlives the IdP&#39;s, so the account icon still renders after the IdP session has expired. The console applies the hint only when it sees an unauthenticated visitor, and then starts the authorization-code flow against that realm instead of asking which realm to sign in to — a question the visitor was never asked when signing into the UI. It is ignored while a console session exists, and while the console carries an <code>error</code> param, so a denied consent cannot loop back into the flow.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Project management</strong> — create and manage collaborative research projects</li><li><strong>Analysis workflows</strong> — define, configure, and monitor distributed analyses</li><li><strong>Node management</strong> — register and manage compute nodes</li><li><strong>Administration</strong> — realm management, user roles, approval workflows</li><li><strong>Real-time updates</strong> — live status via WebSocket (Messenger service)</li><li><strong>Light / dark mode</strong> — class-based color mode with a header toggle</li></ul><h2 id="technology" tabindex="-1">Technology <a class="header-anchor" href="#technology" aria-label="Permalink to &quot;Technology&quot;">​</a></h2><ul><li><strong>Nuxt 4</strong> with SSR</li><li><strong>Vue 3</strong> composition API</li><li><strong>Tailwind CSS v4</strong> via <strong>@privateaim/client-vue-theme</strong> — design tokens, light/dark chrome, card system</li><li><strong>@vuecs/*</strong> component framework + <strong>Iconify</strong> SVG icons</li><li><strong>@privateaim/client-vue</strong> — shared component library</li><li><strong>@privateaim/core-http-kit</strong> — typed HTTP client for Core API</li><li><strong>Authup client libraries</strong> — authentication and authorization UI</li></ul><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons&quot;">​</a></h2><p>The client ships only the icons it actually renders. <code>@nuxt/icon</code>&#39;s standalone vite plugin scans source for <code>&lt;collection&gt;:&lt;name&gt;</code> literals at build time and emits just that subset into <code>virtual:nuxt-icon-bundle/register</code>, which <code>plugins/vuecs.ts</code> imports. Registration goes through <code>addIcon</code> from <code>@iconify/vue</code> — the same global store <code>&lt;VCIcon&gt;</code> reads — so components are unaffected. This replaced registering the full Font Awesome 6 solid + brands collections (1,902 icons, ~429 KB gzip) and cut the client JS payload from ~1,031 KB to ~623 KB gzip.</p><p>The scanned paths are configured in <code>apps/client-ui/icon-bundle.config.ts</code>. They cover this app, <code>@privateaim/client-vue</code>, <code>@privateaim/client-vue-theme</code>, <code>@authup/client-web-kit</code> and <code>@vuecs/icons-font-awesome</code> (whose preset holds the vuecs behavioral defaults — pagination arrows, submit-button, alert and collapse icons — that appear in no hub source file).</p><p>Two consequences for anyone adding an icon:</p><ul><li><strong>Write the icon name as a literal.</strong> A composed name (<code>\`fa6-brands:\${os}\`</code>) is invisible to the scan, so it is never bundled; <code>@iconify/vue</code> then falls back to fetching it from the public Iconify API at runtime. Resolve to literals instead — see <code>FAnalysisBuildStep.vue</code>.</li><li><strong>A path that stops matching fails silently</strong> — an empty icon slot, not a build error. <code>apps/client-ui/test/unit/icon-bundle.spec.ts</code> pins one uniquely-attributable icon per scanned source to catch that.</li></ul>`,27)])])}const p=t(a,[["render",s]]);export{g as __pageData,p as default};
